<?php foreach($axes as $axis):$selectedValues=array_map(fn($v)=>(string)Namira\MartyrCatalog::canonical($db,(int)$v),array_filter((array)($f['axis'][$axis['axis_key']]??[]),fn($v)=>$v!=='')); ?><details class="public-axis-filter" <?= $selectedValues?'open':'' ?>><summary><?= e($axis['title']) ?></summary><input type="search" data-filter-search aria-label="جست‌وجو در <?= e($axis['title']) ?>" placeholder="جست‌وجوی گزینه‌ها"><div class="public-filter-options"><?php if(!$axis['options']): ?><p class="hint">هنوز گزینه‌ای با اطلاعات منتشرشده برای این محور ثبت نشده است.</p><?php elseif($axis['selection_mode']==='single'): ?><label data-filter-option><input type="radio" name="axis[<?= e($axis['axis_key']) ?>][]" value="" <?= !$selectedValues?'checked':'' ?>>همه</label><?php endif ?><?php foreach($axis['options'] as $term): ?><label data-filter-option><input type="<?= $axis['selection_mode']==='single'?'radio':'checkbox' ?>" name="axis[<?= e($axis['axis_key']) ?>][]" value="<?= $term['id'] ?>" <?= in_array((string)$term['id'],$selectedValues,true)?'checked':'' ?>><span><?= e($term['title']) ?></span></label><?php endforeach ?></div></details><?php endforeach ?>
